INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422720, 16421, 'France 24', 'en', 'El Niño, paired with climate change, ''just makes everything so much more dangerous''', 'https://www.france24.com/en/video/20260828-el-ni%C3%B1o-paired-with-climate-change-just-makes-everything-so-much-more-dangerous', 'Annette Young is pleased to welcome Gareth Redmond-King, Head of the International Programme at the Energy and Climate Intelligence Unit. He warns we are entering a period in which climate change is not only intensifying extreme weather but adding greater instability to the climate system itself. Natural phenomena such as El Niño will then amplify, and intensify, that disruption, effectively “fanning the flames of climate change” and making already dangerous extremes even more severe. For Europe, this means that the extreme heat, drought, water shortages, storms and flash flooding we are exper', 'https://s.france24.com/media/display/8935aaa8-a0a5-11f1-a8a1-005056a97e36/w:1024/p:16x9/EN-20260825-181209-182035-CS.jpg', '2026-08-28T09:35:51+00:00', '2026-08-28T12:49:23.820752'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
