INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (429801, 16422, 'South China Morning Post', 'en', 'US Treasury sanctions Hong Kong-based firm over Iran money laundering ties', 'https://www.scmp.com/news/china/diplomacy/article/3365670/us-treasury-sanctions-hong-kong-based-firm-over-iran-money-laundering-ties', 'The United States announced sanctions on a Hong Kong company on Friday for allegedly helping launder funds for a sanctioned Iranian exchange house, the latest Chinese entity to be targeted as part of Washington’s expanded efforts to squeeze Iran’s financial sector. The development comes as Washington has in recent days slapped new Iran-related sanctions on various Chinese entities, prompting Beijing to vow retaliation just weeks before Chinese President Xi Jinping’s expected visit to the...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/29/7df84201-8197-4fb4-94dd-10bbda97035d_0af89659.jpg?itok=prxX-EVe&v=1787955258', '2026-08-28T22:14:19+00:00', '2026-08-29T00:09:28.340805'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (429807, 16422, 'South China Morning Post', 'en', 'As Iran war hits six-month mark, Trump says he’s ‘not in a hurry’', 'https://www.scmp.com/news/world/middle-east/article/3365663/iran-war-hits-six-month-mark-trump-says-hes-not-hurry', 'President Donald Trump arrives at an awkward moment for his presidency on Friday as the US-Israel war against Iran reaches the six-month mark, a notable milestone for a conflict that the Republican leader repeatedly assured Americans would be a “little excursion” lasting a matter of weeks. The war is not over, though Trump claims that through bombs and blockade, he has already devastated Iran’s leadership, military and economy. And this week his administration said it would turn its focus to...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/29/bd721142-e066-4cd9-8314-1e76e411822e_5eb690be.jpg?itok=Zdr77vUi&v=1787937987', '2026-08-28T17:26:37+00:00', '2026-08-29T00:09:28.504526'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
